import{_ as t,a,b as o,c as r,d as n}from"./chunks/notes-toolbar-tags.BP0P4Ij2.js";import{_ as s,o as i,c as l,a2 as d}from"./chunks/framework.Dx-TCpNt.js";const y=JSON.parse('{"title":"Notes","description":"Notes are the reason the panels and alignment exist. A note can hang off a whole page or a single panel; it is written in Markdown and can carry tags, a…","frontmatter":{"description":"Notes are the reason the panels and alignment exist. A note can hang off a whole page or a single panel; it is written in Markdown and can carry tags, a…"},"headers":[],"relativePath":"guide/notes.md","filePath":"guide/notes.md","lastUpdated":1794842635000}'),h={name:"guide/notes.md"};function c(p,e,g,u,m,b){return i(),l("div",null,[...e[0]||(e[0]=[d('<h1 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h1><p>Notes are the reason the panels and alignment exist. A note can hang off a whole page or a single panel; it is written in Markdown and can carry tags, a source and attached screenshots.</p><figure class="shot"><img src="'+t+'" alt="Notes panel with Markdown editor, live preview, tags and the overview tab"><figcaption>The notes column sits to the right of the stage and can be collapsed. The toolbar above the editor inserts Markdown; the tab bar switches between this page and the global overview.</figcaption></figure><h2 id="the-problem-it-solves" tabindex="-1">The problem it solves <a class="header-anchor" href="#the-problem-it-solves" aria-label="Permalink to &quot;The problem it solves&quot;">​</a></h2><p>A remark like “this translation drops the honorific” stops meaning anything the moment it leaves the balloon it refers to. Notes here stay attached to a page or a panel id, so they survive page reordering, template changes and export. The second problem is retrieval: fifty pages later you need every note tagged <code>tone</code>, or everything you learned from one article.</p><h2 id="page-notes-and-panel-notes" tabindex="-1">Page notes and panel notes <a class="header-anchor" href="#page-notes-and-panel-notes" aria-label="Permalink to &quot;Page notes and panel notes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Scope</th><th>When to use</th><th>Stored as</th></tr></thead><tbody><tr><td><strong>Page</strong></td><td>Overall observations, proofreading remarks, questions about a page.</td><td><code>scope: &quot;page&quot;</code>, <code>panelId: null</code></td></tr><tr><td><strong>Panel</strong></td><td>Wording, tone, a specific balloon, a translation difference.</td><td><code>scope: &quot;panel&quot;</code>, <code>panelId: &quot;&lt;panel id&gt;&quot;</code></td></tr></tbody></table><p>Selecting a panel in the workbench or in the compare reader scopes the next note to that panel. With nothing selected, the note is page-scoped. The editor placeholder tells you which scope is active: <em>Capture this panel&#39;s original text…</em> versus <em>Capture observations… for the whole page</em>.</p><h2 id="note-types" tabindex="-1">Note types <a class="header-anchor" href="#note-types" aria-label="Permalink to &quot;Note types&quot;">​</a></h2><p>A page or a panel can hold any number of notes, and every note has a type. The built-in types are <strong>Background</strong> (blue), <strong>Vocabulary</strong> (amber) and <strong>Reaction</strong> (red). When a project enables several languages, each enabled language also gets its own type (for example <strong>Japanese</strong> or <strong>Chinese</strong>); disabled languages do not appear.</p><p>Every note card uses the same visual grammar everywhere it appears — the notes column, the panel detail view and the in-panel blocks in the compare reader:</p><ul><li>the type colour as a variable, with an 8% tint of it as the card surface;</li><li>a 3 px left bar in the full type colour;</li><li>a small type badge with the type name.</li></ul><p>Both light and dark themes keep the tint readable, and a custom colour applies to all three parts at once. Because the type is carried by colour <em>and</em> a label, the cards are still distinguishable without colour vision.</p><p>The notes column is ordered as filter → list → editor. Notes are grouped by type, and the <strong>All</strong> filter shows every group. Choosing a type chip, or <strong>Add note</strong>, starts a note of that type and moves focus into the editor below the list; clicking a type while a draft is open only retags that draft.</p><p>Custom types can be added, renamed, recolored and deleted from the type row; the picker offers a fixed palette plus the current colour. They are stored in <code>noteTypes</code> in <code>data/library.json</code>, so they travel with the library rather than a browser profile. Notes that still reference a deleted type fall back to Background.</p><p>Notes saved before types existed are migrated to Background. When note types were introduced, page documents moved to <code>schemaVersion: 2</code>, and the original version-1 file was kept next to it as <code>&lt;file&gt;.v1.bak</code> (for example <code>3.json.v1.bak</code>). Current page documents are at <code>schemaVersion: 4</code>; older files are migrated on read.</p><p>The panel detail view embeds the same editor, so a panel note can be written without leaving the page. Switching panels, paging or going back flushes the draft first.</p><h2 id="pins-on-the-artwork" tabindex="-1">Pins on the artwork <a class="header-anchor" href="#pins-on-the-artwork" aria-label="Permalink to &quot;Pins on the artwork&quot;">​</a></h2><p>A note can also point at a spot inside the drawing — the balloon that made you stop, a sign in the background, an onomatopoeia.</p><ol><li>Write the note text first; a pin without text is refused.</li><li>Click <strong>Pin on artwork</strong>, then click the artwork. The pin belongs to the note&#39;s language, and the status line confirms it: <em>Pinned in Japanese</em>.</li><li><strong>Remove pin</strong> clears it. While placing, <code>Esc</code> cancels.</li></ol><p>A pin renders as a small dot in the compare reader and in the panel detail view, coloured by note type. Several notes at the same spot do not stack into an unreadable pile: they collapse into one dot with a count, and clicking it opens a popover listing every note there. Pins are stored in the page JSON with the note, so they survive export and import.</p><figure class="shot"><img src="'+a+'" alt="Pins on the artwork in the compare reader: small dots inside a panel and an expanded note popover"><figcaption>Notes pinned to the artwork show as small dots coloured by note type; clicking one opens a popover listing every note at that spot.</figcaption></figure><h2 id="writing-a-note" tabindex="-1">Writing a note <a class="header-anchor" href="#writing-a-note" aria-label="Permalink to &quot;Writing a note&quot;">​</a></h2><figure class="shot"><img src="'+o+'" alt="Notes editor with Markdown toolbar, Edit / Split / Preview toggle, source and tag fields and the scratchpad"><figcaption>The note editor: Markdown toolbar, Edit / Split / Preview, the source and tag fields, and the scratchpad underneath. The scope chip above the editor says whether the next note belongs to the page or a panel.</figcaption></figure><ol><li>Choose a type chip above the list, or click <strong>Add note</strong>. The editor below the list receives focus; if a draft already has content, clicking a type only changes that draft&#39;s type.</li><li>Type Markdown. The toolbar inserts the common syntax:</li></ol><table tabindex="0"><thead><tr><th>Button</th><th>Inserts</th></tr></thead><tbody><tr><td><strong>B</strong></td><td>Bold (<code>Ctrl+B</code>)</td></tr><tr><td><em>I</em></td><td>Italic (<code>Ctrl+I</code>)</td></tr><tr><td>• List</td><td>Bullet list</td></tr><tr><td>❝ Quote</td><td>Block quote</td></tr><tr><td><code>&lt;/&gt;</code></td><td>Inline code</td></tr><tr><td>↗ Link</td><td>Link (<code>Ctrl+K</code>)</td></tr><tr><td>H</td><td>Heading</td></tr><tr><td>S</td><td>Strikethrough</td></tr><tr><td>1.</td><td>Ordered list</td></tr><tr><td>—</td><td>Horizontal rule</td></tr></tbody></table><ol start="3"><li>Choose the mode: <strong>Edit</strong>, <strong>Split</strong> (editor + preview) or <strong>Preview</strong>.</li><li>Press <code>Ctrl+Enter</code> or click <strong>Add note</strong>.</li></ol><p>Rendered output escapes raw HTML; HTML is never executed. Notes written before Markdown support still render as plain text with line breaks.</p><h2 id="tags" tabindex="-1">Tags <a class="header-anchor" href="#tags" aria-label="Permalink to &quot;Tags&quot;">​</a></h2><ul><li>Type a tag and press <code>Enter</code> to add it.</li><li>Tags are stored as an array on the note.</li><li>Usage is aggregated across all pages and offered as suggestions, and the <strong>Filter</strong> row can filter the current page by tag.</li></ul><p>Tags are the cheapest way to build a personal taxonomy: <code>tone</code>, <code>mistranslation</code>, <code>culture</code>, <code>unsure</code>, <code>onomatopoeia</code>.</p><h2 id="attached-images" tabindex="-1">Attached images <a class="header-anchor" href="#attached-images" aria-label="Permalink to &quot;Attached images&quot;">​</a></h2><p>A note can carry screenshots — useful for a reference page, an edition comparison, or a photo of the printed book you refuse to scan.</p><ul><li><strong>Paste</strong> an image into the editor, or <strong>drag and drop</strong> it onto the note form.</li><li><strong>Add images</strong> opens a file picker; each attached image gets a thumbnail with a remove button.</li><li>Images under 400 KB are stored as-is (data URL). Larger images are downscaled to a maximum edge of 1600 px and re-encoded as WebP at quality 0.85.</li><li>Images are stored inside the note&#39;s <code>images</code> array in the page JSON, so they travel with the page in exports and project files. Very large collections make the JSON bigger; prefer a few cropped references over full pages.</li></ul><h2 id="sources" tabindex="-1">Sources <a class="header-anchor" href="#sources" aria-label="Permalink to &quot;Sources&quot;">​</a></h2><p>Each note can carry a source:</p><ul><li><strong>URL</strong> — paste a link. The first URL in the note text is filled in automatically. <strong>Fetch title</strong> tries to read the page title with a 5-second timeout; if fetching is blocked, type the title yourself.</li><li><strong>Free text</strong> — e.g. <code>ChatGPT conversation 2026-05-12</code>, a book title or an interview name.</li></ul><p>The source is displayed under the note and can be toggled with <strong>Hide source</strong>.</p><h2 id="copy-context-for-an-llm" tabindex="-1">Copy context for an LLM <a class="header-anchor" href="#copy-context-for-an-llm" aria-label="Permalink to &quot;Copy context for an LLM&quot;">​</a></h2><p><strong>Copy page context</strong> / <strong>Copy context</strong> assembles a prompt from the current page, the selected panel, the note text, tags and sources.</p><ul><li>The copy dialog has an editable <strong>Template prefix</strong>.</li><li>Supported placeholders: <code>{volume}</code>, <code>{chapter}</code>, <code>{page}</code>, <code>{panel}</code>, <code>{notes}</code>, <code>{text}</code>, <code>{tags}</code>.</li><li>Edits to the template are remembered automatically.</li><li><strong>Preview</strong> shows exactly what will be copied; <strong>Copy</strong> puts it on the clipboard.</li></ul><p>The default template asks the model to explain language points, tone and cultural background, and to point out misunderstandings. Adjust it once for your preferred tutor style and every later copy follows it.</p><h2 id="overview-and-search" tabindex="-1">Overview and search <a class="header-anchor" href="#overview-and-search" aria-label="Permalink to &quot;Overview and search&quot;">​</a></h2><p>The <strong>Overview / search</strong> tab works across the whole library, not just the current page:</p><ul><li>Search text in notes, tags and sources.</li><li>Filter by volume, chapter, page number, tag or source.</li><li>Group results by chapter, tag or source.</li><li>The result header reports how many notes were found across how many pages.</li><li>Click a result to jump to that page and, when the note is panel-scoped, to that panel.</li></ul><p><strong>Clear filters</strong> resets the current query.</p><figure class="shot"><img src="'+r+'" alt="Notes overview and search with filters for volume, chapter and tag, grouped results and a jump list"><figcaption>Overview / search: search text, tags and sources across the whole library, group results by chapter or tag, and click a result to jump to the page and panel.</figcaption></figure><h2 id="scratchpad" tabindex="-1">Scratchpad <a class="header-anchor" href="#scratchpad" aria-label="Permalink to &quot;Scratchpad&quot;">​</a></h2><p>The scratchpad is for thoughts that arrive before you know where they belong — the margin of your brain.</p><ol><li>Type in <strong>Scratchpad</strong> and press <code>Ctrl+Enter</code> or <strong>Save</strong>.</li><li>Later, use <strong>Move to page</strong> or <strong>Move to panel</strong> to file it as a real note.</li></ol><h2 id="editing-and-deleting" tabindex="-1">Editing and deleting <a class="header-anchor" href="#editing-and-deleting" aria-label="Permalink to &quot;Editing and deleting&quot;">​</a></h2><p>Each saved note has <strong>Edit</strong>, <strong>Copy context</strong>, <strong>Filter by tag</strong> and delete actions. The <strong>Rendered / Source</strong> toggle on a note switches between the rendered Markdown and its raw text.</p><p>Deleting, merging or splitting a panel does not throw its notes away: panel notes become page notes, and annotations keep their position by converting the old panel rectangle into page coordinates. When a page is loaded, notes, annotations and alignment offsets that point at a panel that no longer exists are repaired the same way, so editing the layout never silently deletes work.</p><p>Editing reuses the single composer at the top of the notes panel; no second Markdown box opens inside the note card:</p><ul><li>A <strong>Editing an existing note</strong> banner with <strong>Cancel</strong> appears above the editor. Cancel clears the composer and leaves the original note untouched.</li><li>The submit button changes from <strong>Add note</strong> to <strong>Save changes</strong>.</li><li>The <strong>Whole page / Panel</strong> scope toggle is locked while editing, so saving cannot move the note to another scope.</li><li>The note being edited is highlighted in the list; deleting it is the same as cancelling the edit.</li></ul><h2 id="common-pitfalls" tabindex="-1">Common pitfalls <a class="header-anchor" href="#common-pitfalls" aria-label="Permalink to &quot;Common pitfalls&quot;">​</a></h2><ul><li><strong>The note went to the wrong scope.</strong> Check the sentence above the editor: it names the panel number or says <em>whole page</em>. Deselect the panel to write a page note.</li><li><strong><code>Ctrl+Enter</code> did nothing.</strong> Focus must be inside the note editor; the shortcut does not fire from the search field.</li><li><strong>A pasted screenshot is huge.</strong> Images over the limit are downscaled automatically, but full-page screenshots are still heavy; crop first.</li><li><strong>A tag filter hides notes.</strong> The <strong>Filter</strong> row is per page and is not the same as the overview filters.</li><li><strong>Text looks like code.</strong> Fenced blocks need three backticks on their own lines.</li></ul><figure class="shot"><img src="'+n+'" alt="Note editor with the page and panel scope switch, Markdown toolbar, live preview, an attached screenshot and the tag row"><figcaption>The note editor: page / panel scope, Markdown toolbar, live preview, an attached screenshot and the tag row.</figcaption></figure><h2 id="missing-screenshots" tabindex="-1">Missing screenshots <a class="header-anchor" href="#missing-screenshots" aria-label="Permalink to &quot;Missing screenshots&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Figure</th><th>Needed for</th></tr></thead><tbody><tr><td>copy-context dialog</td><td>Template prefix and preview</td></tr></tbody></table><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/KomaYomi-docs/guide/compare">Compare Reader</a> — where most notes are born.</li><li><a href="/KomaYomi-docs/guide/export">Export</a> — how notes become a study document.</li><li><a href="/KomaYomi-docs/guide/shortcuts">Keyboard Shortcuts</a> — editor and global keys.</li></ul>',62)])])}const v=s(h,[["render",c]]);export{y as __pageData,v as default};
